import React, { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { motion } from 'framer-motion';
import {
    CreditCardIcon, BuildingLibraryIcon, BanknotesIcon,
    ShieldCheckIcon, KeyIcon, DocumentTextIcon,
    ArrowPathIcon, CheckCircleIcon, XCircleIcon,
    EyeIcon, EyeSlashIcon
} from '@heroicons/react/24/outline';
import toast from 'react-hot-toast';
import paymentService from '../../services/paymentService';
import StatCard from '../../components/ui/StatCard';
import SectionCard from '../../components/ui/SectionCard';
import StatusBadge from '../../components/ui/StatusBadge';
import EmptyState from '../../components/ui/EmptyState';
import Pagination from '../../components/ui/Pagination';
import Modal from '../../components/ui/Modal';
import PageHeader from '../../components/ui/PageHeader';
import { CreditCard, Building2, DollarSign, ToggleLeft, ToggleRight } from 'lucide-react';

const PaymentSettings = () => {
    const [toggling, setToggling] = useState(null);
    const [page, setPage] = useState(1);
    const queryClient = useQueryClient();

    const { data: config, isLoading: configLoading } = useQuery({
        queryKey: ['payment-config'],
        queryFn: paymentService.getPaymentConfig
    });

    const { data: transactions, isLoading: txLoading } = useQuery({
        queryKey: ['payment-transactions', { page }],
        queryFn: () => paymentService.getTransactionHistory({ page, limit: 10 })
    });

    const toggleMutation = useMutation({
        mutationFn: ({ method, enabled }) => paymentService.togglePaymentMethod(method, enabled),
        onSuccess: () => {
            toast.success('Payment method updated');
            queryClient.invalidateQueries(['payment-config']);
            setToggling(null);
        },
        onError: () => {
            toast.error('Failed to update');
            setToggling(null);
        }
    });

    return (
        <div className="space-y-6">
            <PageHeader
                icon={CreditCardIcon}
                title="Payment Settings"
                description="Manage payment methods and view transactions"
            />

            {/* Payment Methods Toggle */}
            <SectionCard title="Payment Methods" subtitle="Enable or disable payment options">
                <div className="space-y-4">
                    {/* Online Payment */}
                    <div className="flex items-center justify-between p-5 bg-slate-50 dark:bg-brand-800/50 rounded-2xl border border-slate-200 dark:border-brand-700">
                        <div className="flex items-center gap-4">
                            <div className="p-3 bg-brand-100 dark:bg-brand-800 rounded-xl">
                                <CreditCard className="w-6 h-6 text-brand-600 dark:text-brand-400" />
                            </div>
                            <div>
                                <p className="font-semibold text-brand-800 dark:text-white">Online Payment</p>
                                <p className="text-sm text-slate-500">Paystack & Flutterwave integration</p>
                                <div className="flex items-center gap-2 mt-1">
                                    <span className="text-xs px-2 py-0.5 bg-purple-100 text-purple-700 rounded-full font-medium">Paystack</span>
                                    <span className="text-xs px-2 py-0.5 bg-teal-100 text-teal-700 rounded-full font-medium">Flutterwave</span>
                                </div>
                            </div>
                        </div>
                        <button
                            onClick={() => setToggling('online')}
                            disabled={toggleMutation.isLoading}
                            className="relative"
                        >
                            {configLoading ? (
                                <div className="h-8 w-14 bg-slate-200 dark:bg-brand-700 rounded-full animate-pulse" />
                            ) : config?.onlineEnabled ? (
                                <ToggleRight className="h-8 w-14 text-emerald-500" />
                            ) : (
                                <ToggleLeft className="h-8 w-14 text-slate-300" />
                            )}
                        </button>
                    </div>

                    {/* Pay on Delivery */}
                    <div className="flex items-center justify-between p-5 bg-slate-50 dark:bg-brand-800/50 rounded-2xl border border-slate-200 dark:border-brand-700">
                        <div className="flex items-center gap-4">
                            <div className="p-3 bg-teal-100 dark:bg-teal-900/30 rounded-xl">
                                <BanknotesIcon className="w-6 h-6 text-teal-600" />
                            </div>
                            <div>
                                <p className="font-semibold text-brand-800 dark:text-white">Pay on Delivery</p>
                                <p className="text-sm text-slate-500">Cash or card payment upon delivery</p>
                            </div>
                        </div>
                        <button
                            onClick={() => setToggling('delivery')}
                            disabled={toggleMutation.isLoading}
                            className="relative"
                        >
                            {configLoading ? (
                                <div className="h-8 w-14 bg-slate-200 dark:bg-brand-700 rounded-full animate-pulse" />
                            ) : config?.deliveryEnabled ? (
                                <ToggleRight className="h-8 w-14 text-emerald-500" />
                            ) : (
                                <ToggleLeft className="h-8 w-14 text-slate-300" />
                            )}
                        </button>
                    </div>
                </div>
            </SectionCard>

            {/* API Keys Configuration */}
            <SectionCard title="Payment Gateway Configuration" subtitle="API keys and webhook settings" icon={KeyIcon}>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div className="p-5 bg-slate-50 dark:bg-brand-800/50 rounded-2xl border border-slate-200 dark:border-brand-700">
                        <div className="flex items-center gap-3 mb-4">
                            <BuildingLibraryIcon className="w-6 h-6 text-purple-600" />
                            <div>
                                <h4 className="font-semibold text-brand-800 dark:text-white">Paystack</h4>
                                <StatusBadge status="active" label="Configured" size="sm" />
                            </div>
                        </div>
                        <div className="space-y-2 text-sm">
                            <div className="flex justify-between">
                                <span className="text-slate-500">Public Key</span>
                                <span className="font-mono text-xs">pk_test_••••••••</span>
                            </div>
                            <div className="flex justify-between">
                                <span className="text-slate-500">Webhook URL</span>
                                <span className="font-mono text-xs">/api/payments/webhook/paystack</span>
                            </div>
                        </div>
                    </div>

                    <div className="p-5 bg-slate-50 dark:bg-brand-800/50 rounded-2xl border border-slate-200 dark:border-brand-700">
                        <div className="flex items-center gap-3 mb-4">
                            <BuildingLibraryIcon className="w-6 h-6 text-teal-600" />
                            <div>
                                <h4 className="font-semibold text-brand-800 dark:text-white">Flutterwave</h4>
                                <StatusBadge status="active" label="Configured" size="sm" />
                            </div>
                        </div>
                        <div className="space-y-2 text-sm">
                            <div className="flex justify-between">
                                <span className="text-slate-500">Public Key</span>
                                <span className="font-mono text-xs">FLWPUBK_TEST_••••••••</span>
                            </div>
                            <div className="flex justify-between">
                                <span className="text-slate-500">Webhook URL</span>
                                <span className="font-mono text-xs">/api/payments/webhook/flutterwave</span>
                            </div>
                        </div>
                    </div>
                </div>
            </SectionCard>

            {/* Transaction History */}
            <SectionCard
                title="Transaction History"
                subtitle="Recent payment transactions"
                icon={DocumentTextIcon}
                badge={`${transactions?.pagination?.total || 0} total`}
            >
                {txLoading ? (
                    <div className="space-y-3">
                        {[...Array(5)].map((_, i) => (
                            <div key={i} className="animate-pulse flex items-center gap-4 py-3">
                                <div className="h-4 w-24 bg-slate-200 dark:bg-brand-700 rounded" />
                                <div className="h-4 w-16 bg-slate-200 dark:bg-brand-700 rounded" />
                                <div className="h-4 w-20 bg-slate-200 dark:bg-brand-700 rounded" />
                                <div className="h-6 w-20 bg-slate-200 dark:bg-brand-700 rounded-full ml-auto" />
                            </div>
                        ))}
                    </div>
                ) : (!transactions?.data || transactions.data.length === 0) ? (
                    <EmptyState
                        icon={DocumentTextIcon}
                        title="No transactions yet"
                        description="Payment transactions will appear here when customers make payments."
                    />
                ) : (
                    <>
                        <div className="overflow-x-auto">
                            <table className="min-w-full divide-y divide-slate-100 dark:divide-brand-700">
                                <thead>
                                    <tr className="bg-slate-50/50 dark:bg-brand-800/30">
                                        <th className="px-4 py-4 text-left text-xs font-semibold text-slate-500 uppercase">Reference</th>
                                        <th className="px-4 py-4 text-left text-xs font-semibold text-slate-500 uppercase">Provider</th>
                                        <th className="px-4 py-4 text-right text-xs font-semibold text-slate-500 uppercase">Amount</th>
                                        <th className="px-4 py-4 text-center text-xs font-semibold text-slate-500 uppercase">Status</th>
                                        <th className="px-4 py-4 text-right text-xs font-semibold text-slate-500 uppercase">Date</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-slate-50 dark:divide-brand-700">
                                    {transactions.data.map((tx, idx) => (
                                        <motion.tr
                                            key={tx.id}
                                            initial={{ opacity: 0 }}
                                            animate={{ opacity: 1 }}
                                            transition={{ delay: idx * 0.02 }}
                                            className="hover:bg-brand-50/30 dark:hover:bg-brand-800/20 transition-colors"
                                        >
                                            <td className="px-4 py-4 text-sm font-mono text-slate-500">{tx.reference}</td>
                                            <td className="px-4 py-4 text-sm capitalize font-medium text-brand-800 dark:text-white">{tx.provider}</td>
                                            <td className="px-4 py-4 text-sm font-bold text-right">${parseFloat(tx.amount).toFixed(2)}</td>
                                            <td className="px-4 py-4 text-center">
                                                <StatusBadge status={tx.status} size="sm" />
                                            </td>
                                            <td className="px-4 py-4 text-xs text-slate-500 text-right">
                                                {new Date(tx.created_at).toLocaleDateString()}
                                            </td>
                                        </motion.tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                        <Pagination pagination={transactions?.pagination} onPageChange={setPage} />
                    </>
                )}
            </SectionCard>

            {/* Toggle Confirmation Modal */}
            <Modal
                isOpen={!!toggling}
                onClose={() => setToggling(null)}
                title={config?.[toggling === 'online' ? 'onlineEnabled' : 'deliveryEnabled'] ? 'Disable Payment Method' : 'Enable Payment Method'}
                size="sm"
                loading={toggleMutation.isLoading}
                footer={
                    <>
                        <button onClick={() => setToggling(null)} className="px-5 py-2.5 border-2 border-slate-300 dark:border-brand-600 rounded-xl hover:bg-white dark:hover:bg-brand-800 transition font-medium text-sm">
                            Cancel
                        </button>
                        <button
                            onClick={() => toggleMutation.mutate({
                                method: toggling,
                                enabled: toggling === 'online' ? !config?.onlineEnabled : !config?.deliveryEnabled
                            })}
                            disabled={toggleMutation.isLoading}
                            className={`px-6 py-2.5 text-white rounded-xl transition-all font-semibold text-sm shadow-lg ${config?.[toggling === 'online' ? 'onlineEnabled' : 'deliveryEnabled']
                                    ? 'bg-gradient-to-r from-rose-600 to-rose-700 hover:from-rose-700 hover:to-rose-800 shadow-rose-500/25'
                                    : 'bg-gradient-to-r from-emerald-600 to-emerald-700 hover:from-emerald-700 hover:to-emerald-800 shadow-emerald-500/25'
                                }`}
                        >
                            {toggleMutation.isLoading ? 'Updating...' : config?.[toggling === 'online' ? 'onlineEnabled' : 'deliveryEnabled'] ? 'Disable' : 'Enable'}
                        </button>
                    </>
                }
            >
                <p className="text-slate-600 dark:text-slate-400">
                    Are you sure you want to <strong>{config?.[toggling === 'online' ? 'onlineEnabled' : 'deliveryEnabled'] ? 'disable' : 'enable'}</strong> {toggling === 'online' ? 'online payments' : 'pay on delivery'}?
                </p>
            </Modal>
        </div>
    );
};

export default PaymentSettings;
